export type Period = 'DAY' | 'L7' | 'L30';
export type MetricType = 'money' | 'count' | 'rate';
export type MetricKey =
  | 'confirmGmv' | 'confirmBuyerNum' | 'dealTransRate' | 'unitPrice' | 'obRate' | 'confirmRfxNum' | 'confirmProdQt'
  | 'startedGmv' | 'startedBuyerNum' | 'startedTransRate' | 'startedRfxNum'
  | 'pdPv' | 'pdUv' | 'expoPv' | 'avgUvValue'
  | 'addcartUv' | 'addcartIcNum' | 'addfavUv';

export interface StoreInfo {
  id: number;
  name: string;
  alias: string;
  sellerId: string;
  accountId: number;
  account: string;
}

export interface PunishRow {
  id: string;
  date: string;
  reason: string;
  type: string;
  status: string;
}

export type WisSummary = Record<MetricKey, number> & {
  statDate: string;
  timeNo: string;
};

export interface HistoryData {
  dates: string[];
  series: Record<MetricKey, number[]>;
}

export interface TagDetail {
  name: string;
  detail: string;
  compareLastMonth: number;
  monthAvg: string;
  desired: string;
  storeState: string;
  score: number;
  category: string;
  position: number;
}

export interface GroupRow {
  storeId: number;
  storeName: string;
  aliasName: string;
  level: string;
  score: number;
  todayScore: number;
  punishCount: number;
  latestPunishTime: string;
  wis: Record<MetricKey, number>;
  history: { statDate: string; confirmGmv: number }[];
  tags: TagDetail[];
}

export interface KpiMetric {
  key: MetricKey;
  label: string;
  type: MetricType;
  tip: string;
}

export interface DataTab {
  key: string;
  label: string;
  metrics: KpiMetric[];
}

export interface GroupColumn {
  key: MetricKey;
  label: string;
  width: number;
  type: MetricType;
}

export interface CapabilityMetric {
  name: string;
  tip: string;
  compare: string;
  trend: 'up' | 'down';
  monthAvg: string;
  suggest: string;
  storeCurrent: string;
  score: number;
}

